INSERT INTO repo_cf_skills (cf_skill_id, education_level, sub_heading, text, status) VALUES ('CFS_SDG06_ADULT_015', 'Adult education', 'Climate resilience', 'Participate in or support transboundary and regional water co-operation efforts, using shared tools and frameworks for joint water monitoring, risk management and dialogue.', 'Active'), ('CFS_SDG06_ADULT_016', 'Adult education', 'Livelihoods, health and innovation', 'Integrate clean water and sanitation practices with community health and livelihood improvement strategies to enhance overall wellbeing and productivity.', 'Active'), ('CFS_SDG06_ADULT_017', 'Adult education', 'Livelihoods, health and innovation', 'Support or initiate micro-credit projects that fund water-related enterprises, such as water kiosks, community taps or hygiene product distribution.', 'Active'), ('CFS_SDG07_SEC_001', 'Secondary education', 'Critical thinking and data analysis', 'Calculate ecological footprints to evaluate the impact of personal and collective energy choices.', 'Active'), ('CFS_SDG07_SEC_002', 'Secondary education', 'Critical thinking and data analysis', 'Compare efficiency, affordability and sustainability of energy systems using real-world data and case studies.', 'Active'), ('CFS_SDG07_SEC_003', 'Secondary education', 'Inquiry and research', 'Create diagrams or models illustrating how specific energy systems (wind turbines, geothermal plants) work.', 'Active'), ('CFS_SDG07_SEC_004', 'Secondary education', 'Inquiry and research', 'Research renewable energy solutions suited to local or regional needs and propose adaptations.', 'Active'), ('CFS_SDG07_SEC_005', 'Secondary education', 'Problem solving and innovation', 'Design and prototype alternative energy solutions (solar cookers, energy-saving school designs).', 'Active'), ('CFS_SDG07_SEC_006', 'Secondary education', 'Problem solving and innovation', 'Conduct school or home energy audits to identify inefficiencies and recommend improvements.', 'Active'), ('CFS_SDG07_SE